insert into criterios_res3100 (llave, numero, item, pagina, criterio, grupo_res3100_id, servicio_res3100_id, numeral_grupo, numeral_servicio, estandar, complejidad, modalidad) values
  ('1;1. El talento humano en salud y otros profesionales que se relacionan con la atención o resultados en salud de los usuarios, cuentan con los títulos, según aplique, de educación superior o certificados de aptitud ocupacional, expedidos por la entidad educativa competente. En el caso de títulos o certificados obtenidos en el extranjero, copia de la resolución de convalidación expedida por el Ministerio de Educación Nacional.', 1, '1', 59, '1. El talento humano en salud y otros profesionales que se relacionan con la atención o resultados en salud de los usuarios, cuentan con los títulos, según aplique, de educación superior o certificados de aptitud ocupacional, expedidos por la entidad educativa competente. En el caso de títulos o certificados obtenidos en el extranjero, copia de la resolución de convalidación expedida por el Ministerio de Educación Nacional.', (select id from grupos_res3100 where numeral = '11.1'), (select id from servicios_res3100 where numeral = '11.1'), '11.1', '11.1.1', 'Estándar de Talento Humano', 'Todas', 'Todas'),
  ('2;2. El talento humano en salud cuenta con copia de la resolución de autorización del ejercicio expedido por la autoridad competente o inscripción en el Registro Único Nacional de Talento Humano en Salud -ReTHUS.', 2, '2', 59, '2. El talento humano en salud cuenta con copia de la resolución de autorización del ejercicio expedido por la autoridad competente o inscripción en el Registro Único Nacional de Talento Humano en Salud -ReTHUS.', (select id from grupos_res3100 where numeral = '11.1'), (select id from servicios_res3100 where numeral = '11.1'), '11.1', '11.1.1', 'Estándar de Talento Humano', 'Todas', 'Todas'),
  ('3;3. El prestador de servicios de salud determina la cantidad necesaria de talento humano requerido para cada uno de los servicios ofertados y prestados, de acuerdo con la capacidad instalada, la relación entre oferta y demanda, la oportunidad en la prestación, tiempo de la atención y el riesgo en la atención. Este criterio no aplica para el profesional independiente de salud.', 3, '3', 59, '3. El prestador de servicios de salud determina la cantidad necesaria de talento humano requerido para cada uno de los servicios ofertados y prestados, de acuerdo con la capacidad instalada, la relación entre oferta y demanda, la oportunidad en la prestación, tiempo de la atención y el riesgo en la atención. Este criterio no aplica para el profesional independiente de salud.', (select id from grupos_res3100 where numeral = '11.1'), (select id from servicios_res3100 where numeral = '11.1'), '11.1', '11.1.1', 'Estándar de Talento Humano', 'Todas', 'Todas'),
  ('4;4. El prestador de servicios de salud que actúe como escenario de práctica formativa en el área de la salud, cuenta con:', 4, '4', 59, '4. El prestador de servicios de salud que actúe como escenario de práctica formativa en el área de la salud, cuenta con:', (select id from grupos_res3100 where numeral = '11.1'), (select id from servicios_res3100 where numeral = '11.1'), '11.1', '11.1.1', 'Estándar de Talento Humano', 'Todas', 'Todas'),
  ('4.1;4.1. Convenio vigente con la institución educativa autorizada por la entidad competente.', 5, '4.1', 59, '4.1. Convenio vigente con la institución educativa autorizada por la entidad competente.', (select id from grupos_res3100 where numeral = '11.1'), (select id from servicios_res3100 where numeral = '11.1'), '11.1', '11.1.1', 'Estándar de Talento Humano', 'Todas', 'Todas'),
